// TH16 v1.00a Stage 2 mid-stage wave -> training card th16_s2_w01.
// Source ECL (st02.ecl.txt):
//   MainSub00   880-894  entry, right arm: enmCreateM (child mirror=1), %A=+192
//   MainSub00b  896-910  entry, left arm:  enmCreate  (mirror=0),      %A=-192
//   GirlA01       6-22   dependency: motion
//   GirlA01_at   24-70   dependency: fan emitter
//   GirlBlueA01e 297-307 dependency: wrapper (!NHL spawns GirlA01_at)
//   GirlRedA01e  698-708 dependency: wrapper (!NHL spawns GirlA01_at)
// Th16 type 8/color 2 from transcribe/th16/touhou-bullets.ecl (TH16_RICE).
const TH16_RICE: int = 480;
const BULLET_RED: int = 2;

// 120-frame shell buffer + source attack window (see report.md) + tail margin.
const TIME_LIMIT: int = 1100;
const OPENING_BUFFER: int = 120;

// GirlA01_at 24-70: one config, then `diffI($A,3,3,8,12)` waves spaced by a
// difficulty-dependent random wait.
async sub girl_at(rank: int) {
    // 0030-0039: etCount(0,[-1],1) -> !E/!N/!H 1, !LO 3.
    var cnt: int = 1;
    // 0041-0050: pushed speed !E/!N 2.0, !H/!LO 3.0; single layer uses s0 only.
    var speed: fx = 2fx;
    // 0053: diffI($A,3,3,8,12) -> wave count.
    var shots: int = 3;
    // 0056-0065: wait !E/!N 40+$RAND%140, !H 30+$RAND%20, !LO 20+$RAND%20.
    var wbase: int = 40;
    var wspan: int = 140;
    if rank == RANK_HARD {
        shots = 8;
        wbase = 30;
        wspan = 20;
    }
    if rank == RANK_LUNATIC {
        cnt = 3;
        speed = 3fx;
        shots = 12;
        wbase = 20;
        wspan = 20;
    }

    // 0052: etAngle(0, 1.5707964f + %RANDF2*0.17453292f, 0.6981317f)
    // -> 90deg +-10deg, 40deg spacing; %RANDF2 sampled once per enemy before
    // the wave loop (the earlier 0040 etAngle is overwritten by this one).
    var rc: int = rand(65536) - 32768;
    var center: angle = (16384 + rc * 1820 / 32768) as angle;

    for wave in 0..shots {
        // 0065: wait([-1]) with the source $RAND % span above.
        wait(wbase + rand(wspan));
        // 0066/0027: etAim(0,1) fixed-direction fan, N=cnt. Source order
        // F(3,k) = 0, -40deg, +40deg.
        if cnt == 1 {
            emit(speed, center);
        } else {
            emit(speed, center);
            emit(speed, center - 40deg);
            emit(speed, center + 40deg);
        }
    }
}

// Bullet EX 0x2 ANIM a=1 (0051): birth animation itself is omitted, but the
// entry displacement `position -= 4 * velocity` along the bullet angle stays.
sub emit(speed: fx, a: angle) {
    var ox: fx = 4fx * speed * cos(a);
    var oy: fx = 4fx * speed * sin(a);
    _ = fire(TH16_RICE, BULLET_RED, $self_x - ox, $self_y - oy, speed, a, none, none);
}

// GirlBlueA01e / GirlRedA01e: !NHL starts GirlA01_at async, then runs GirlA01.
async sub girl(mirror: int, rank: int) {
    set_invuln(65535);
    // 0009/0010: setHurtbox(24,24) -> r=12, setHitbox(16,16) -> r=8.
    set_hurtbox(12fx);
    set_hitbox(8fx);
    if rank >= RANK_NORMAL {
        spawn girl_at(rank);
    }

    // 0011-0015: moveVel / moveVelTime(mode 0). Mirror reflects the x axis at
    // the instruction write point, so the right arm uses pi-a (M create).
    var a0: angle = 67.5deg;
    var a1: angle = 22.5deg;
    var a2: angle = -11.25deg;
    if mirror != 0 {
        a0 = 180deg - a0;
        a1 = 180deg - a1;
        a2 = 180deg - a2;
    }
    move_vel(0, a0, 2fx, EASE_LINEAR);
    wait(30);
    move_vel(60, a1, 1fx, EASE_LINEAR);
    wait(60);
    move_vel(60, a2, 2fx, EASE_LINEAR);
    // 0017-0020: endless wait loop keeps the enemy alive until it leaves.
    loop { wait(1000); }
}

// MainSub00 / MainSub00b: $B=5, each round creates red then blue 20 frames
// apart, 20 frames after blue. hp 100, score 1000, item dropped (reward
// path omitted -> drop_table 0).
sub arm(x: fx, mirror: int, rank: int) {
    for i in 0..5 {
        _ = spawn_enemy(x, -16fx, 100, 0, 1000, 0, girl(mirror, rank));
        wait(20);
        _ = spawn_enemy(x, -16fx, 100, 0, 1000, 0, girl(mirror, rank));
        wait(20);
    }
}

// MainFront 790-792: MainSub00b is async, MainSub00 runs synchronously.
async sub arm_left(rank: int) {
    arm(-192fx, 0, rank);
}

async sub pattern() {
    wait(OPENING_BUFFER);
    var rank: int = global(GVAR_RANK);
    spawn arm_left(rank);
    arm(192fx, 1, rank);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
